function formatMoney(value) {
  const num = Number(value || 0);
  if (!Number.isFinite(num)) return 'n/a';
  return '$' + new Intl.NumberFormat('en-US', { maximumFractionDigits: 2 }).format(num);
}

async function fetchWithRetry(url, options = {}, retries = 2) {
  let lastResponse = null;

  for (let attempt = 0; attempt <= retries; attempt += 1) {
    const response = await fetch(url, options);
    lastResponse = response;

    if (response.status !== 429 || attempt === retries) {
      return response;
    }

    await new Promise(resolve => setTimeout(resolve, 250 * (attempt + 1)));
  }

  return lastResponse;
}

async function getMarketCap() {
  if (!state.mint) {
    console.log('Set a mint first with <MINT> or `mint <address>`');
    return null;
  }

  const url = 'https://frontend-api-v3.pump.fun/coins?query=' + encodeURIComponent(state.mint);

  try {
    const response = await fetchWithRetry(url, {
      headers: {
        Accept: 'application/json',
        'User-Agent': 'Mozilla/5.0',
      },
    }, 2);

    if (!response || !response.ok) {
      const status = response ? response.status : 'unknown';
      console.log('MCAP unavailable for mint ' + state.mint + ' (HTTP ' + status + ').');
      return null;
    }

    const data = await response.json();
    const list = Array.isArray(data) ? data : [];
    const token = list.find(item => String(item.mint || '').toLowerCase() === state.mint.toLowerCase()) || list[0];

    const value = Number(token && (token.market_cap_usd ?? token.usd_market_cap ?? token.market_cap_quote));
    if (!Number.isFinite(value)) {
      console.log('MCAP unavailable for mint ' + state.mint + '.');
      return null;
    }

    console.log('MCAP: ' + formatMoney(value) + ' | mint=' + state.mint);
    return value;
  } catch (error) {
    console.log('MCAP lookup failed: ' + String(error.message || error));
    return null;
  }
}

