async function getMarketCap() {
  if (!state.mint) {
    console.log('Set a mint first with <MINT> or `mint <address>`');
    return null;
  }

  const url = 'https://frontend-api-v3.pump.fun/coins?query=' + encodeURIComponent(state.mint);

  try {
    const response = await fetch(url, {
      headers: {
        Accept: 'application/json',
        'User-Agent': 'Mozilla/5.0',
      },
    });

    if (response.status === 429) {
      console.log('Pump.fun rate limited the MCAP lookup. Try again in a moment.');
      return null;
    }

    if (!response.ok) {
      console.log('MCAP unavailable for mint ' + state.mint + ' (HTTP ' + response.status + ').');
      return null;
    }

    const data = await response.json();
    const list = Array.isArray(data) ? data : [];
    const token = list.find(item => String(item.mint || '').toLowerCase() === state.mint.toLowerCase()) || list[0];

    const value = Number(token && (token.market_cap_usd ?? token.usd_market_cap ?? token.market_cap_quote));
    if (!Number.isFinite(value)) {
      console.log('MCAP unavailable for mint ' + state.mint + '.');
      return null;
    }

    console.log('MCAP: ' + formatMoney(value) + ' | mint=' + state.mint);
    return value;
