    if (lower === 'trade on') {
      state.trade = true;
      console.log('Real trade mode on.');
      rl.prompt();
      return;
    }

    if (lower === 'trade off') {
      state.trade = false;
      console.log('Real trade mode off.');
      rl.prompt();
      return;
    }

    if (lower.startsWith('buy')) {
      const amount = input.slice(3).trim();
      await buy(amount || '0.01');
      rl.prompt();
      return;
    }

    if (lower.startsWith('sell')) {
      const percent = input.slice(4).trim();
      await sell(percent || 100);
      rl.prompt();
      return;
    }

    if (isMintLike(input)) {
      state.mint = input.trim();
      if (state.websocket) {
        state.websocket.send(JSON.stringify({ method: 'subscribeTokenTrade', keys: [state.mint] }));
      }
      console.log('Current mint set to: ' + state.mint);
      rl.prompt();
      return;
    }

    if (lower.startsWith('mint ')) {
      state.mint = input.slice(4).trim();
      console.log('Current mint set to: ' + state.mint);
      rl.prompt();
      return;
    }

    console.log('Unknown command. Type "help" for commands.');
    rl.prompt();
  });

  rl.on('close', () => process.exit(0));
}

(async function start() {
  fillStateFromEnv();
  banner();
  printHelp();
  if ((state.apiKey || state.publicWallet) && state.mint) {
