  const key = String(name || '').trim().toLowerCase();
  if (!key) {
    console.log('Usage: stop [momentum|meanReversion|breakout]');
    return;
  }
  state.watchedStrategies = state.watchedStrategies.filter(v => v !== key);
  console.log('Stopped strategy: ' + key);
}

async function tradeRequest(action, mint, amount, denominatedInSol, slippage = 10) {
  if (!state.apiKey) {
